def public_lesson(lesson: dict[str, Any], include_answers: bool = False) -> dict[str, Any]:
    result = {key: value for key, value in lesson.items() if key != "practice"}
    result["practice"] = []
    for exercise in lesson["practice"]:
        item = {key: value for key, value in exercise.items() if key != "options"}
        item["options"] = [{key: value for key, value in option.items() if include_answers or key in {"id", "text"}} for option in exercise["options"]]
        result["practice"].append(item)
    return result
